INSERT INTO roles (name, description) VALUES
  ('admin', 'Administrator with full access'),
  ('editor', 'Can create and edit content'),
  ('viewer', 'Can view content only');

-- DOWN
DELETE FROM roles WHERE name IN ('admin', 'editor', 'viewer');
```

## Running Migrations

```bash
